mapper.select:
SELECT * FROM wkf_inventory_item
WHERE item_id = #{itemId}
AND lot_number = #{lotNumber}
AND (location_id = #{locationId}
     OR location_id IN (SELECT id FROM adm_organization
                        WHERE name = #{locationId} AND is_deleted = 0))
AND is_deleted = 0
LIMIT 1

mapper.update:
UPDATE wkf_inventory_item
SET quantity = quantity + #{delta},
version = version + 1,
updated_at = NOW(),
updated_by = #{operatorId}
WHERE id = #{id}
AND version = #{version}
AND is_deleted = 0
